                break

    if not inventory_has:
        # broader exploration: use admissible commands
        for _ in range(20):
            if inventory_has:
                break
            adm = get_admissible()
            moved = False
            for cmd in adm:
                if cmd.startswith("go to ") and cmd[6:] not in visited:
                    c = cmd[6:]
                    visited.add(c)
                    resp = go(cmd)
                    if "closed" in resp:
                        go("open %s" % c)
                    if try_take_from_current(obj_type):
                        inventory_has = True
                        break
                    moved = True
            if not moved:
                break

    # Now cool the object with fridge
    if inventory_has:
        # find fridge
        fridge = None
        text = obs()
        for m in re.finditer(r"fridge\s+\d+", text):
            fridge = m.group(0)
            break
        if fridge is None:
            adm = get_admissible()
            for cmd in adm:
                if "fridge" in cmd:
                    fridge = re.search(r"fridge\s+\d+", cmd)
                    if fridge:
                        fridge = fridge.group(0)
                        break
        if fridge:
            go("go to %s" % fridge)
            # open if closed
            if "closed" in obs():
                go("open %s" % fridge)
            obj_name = None
            # find in inventory
            inv = obs()
            for m in re.finditer(r"([a-z]+(?:\s+[a-z]+)*\s+\d+)", inv):
                name = m.group(1)
                base = re.sub(r"\s*\d+$", "", name).strip()
                if base == obj_type:
                    obj_name = name
                    break
            if obj_name is None:
                # try any admissible cool command
                for cmd in get_admissible():
                    if cmd.startswith("cool "):
                        obj_name = cmd.split()[1]
                        break
            if obj_name:
                go("cool %s with %s" % (obj_name, fridge))

        # Now move to target receptacle
        target = None
        # find target receptacle in current room listing
        text = obs()
        for m in re.finditer(r"([a-z]+(?:\s+[a-z]+)*\s+\d+)", text):
            c = m.group(1)
            base = re.sub(r"\s*\d+$", "", c).strip()
            if base == rec_type:
                target = c
                break
        if target is None:
            # go to it directly
            target = rec_type + " 1"
        go("go to %s" % target)
        if "closed" in obs():
            go("open %s" % target)
        # find object in inventory
        obj_name = None
        inv = obs()
        for m in re.finditer(r"([a-z]+(?:\s+[a-z]+)*\s+\d+)", inv):
            name = m.group(1)
            base = re.sub(r"\s*\d+$", "", name).strip()
            if base == obj_type:
                obj_name = name
                break
        if obj_name is None:
            for cmd in get_admissible():
                if cmd.startswith("move "):
                    obj_name = cmd.split()[1]
                    break
        if obj_name:
            go("move %s to %s" % (obj_name, target))
